package org.apache.commons.math3.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.analysis.UnivariateFunction;
import org.apache.commons.math3.convergence.ConvergenceChecker;
import org.apache.commons.math3.convergence.MaxIterConvergenceChecker;
import org.apache.commons.math3.convergence.RelativeConvergenceChecker;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.optim.univariate.UnivariateObjectiveFunction;
import org.apache.commons.math3.optim.univariate.UnivariatePointValuePair;
import org.apache.commons.math3.optimization.ConvergenceChecker;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for BrentOptimizer.doOptimize().
 * Since doOptimize is protected, we use a subclass to expose it for testing.
 */
public class BrentOptimizer_doOptimize_TriageGen1Test {

    private static class TestableBrentOptimizer extends BrentOptimizer {
        public TestableBrentOptimizer(double rel, double abs) {
            super(rel, abs);
        }

        public TestableBrentOptimizer(double rel, double abs, ConvergenceChecker<UnivariatePointValuePair> checker) {
            super(rel, abs, checker);
        }

        @Override
        public UnivariatePointValuePair doOptimize() {
            return super.doOptimize();
        }
    }

    /**
     * Test minimization of a simple parabola: f(x) = (x-2)^2 + 5.
     * Minimum is at x=2, f(x)=5.
     */
    @Test
    public void testMinimizeParabola() {
        UnivariateFunction function = x -> Math.pow(x - 2.0, 2) + 5.0;
        BrentOptimizer optimizer = new TestableBrentOptimizer(1e-10, 1e-10) {
            @Override
            protected double computeObjectiveValue(double x) {
                return function.value(x);
            }
            @Override
            protected double getMin() { return 0.0; }
            @Override
            protected double getMax() { return 5.0; }
            @Override
            protected double getStartValue() { return 3.0; }
            @Override
            protected GoalType getGoalType() { return GoalType.MINIMIZE; }
        };

        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(2.0, result.getPoint(), 1e-7);
        assertEquals(5.0, result.getValue(), 1e-7);
    }

    /**
     * Test maximization of a simple parabola: f(x) = -(x-2)^2 + 5.
     * Maximum is at x=2, f(x)=5.
     */
    @Test
    public void testMaximizeParabola() {
        UnivariateFunction function = x -> -Math.pow(x - 2.0, 2) + 5.0;
        BrentOptimizer optimizer = new TestableBrentOptimizer(1e-10, 1e-10) {
            @Override
            protected double computeObjectiveValue(double x) {
                return function.value(x);
            }
            @Override
            protected double getMin() { return 0.0; }
            @Override
            protected double getMax() { return 5.0; }
            @Override
            protected double getStartValue() { return 3.0; }
            @Override
            protected GoalType getGoalType() { return GoalType.MAXIMIZE; }
        };

        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(2.0, result.getPoint(), 1e-7);
        assertEquals(5.0, result.getValue(), 1e-7);
    }

    /**
     * Tests the branch where lo > hi.
     */
    @Test
    public void testReverseBounds() {
        UnivariateFunction function = x -> Math.pow(x - 1.0, 2);
        BrentOptimizer optimizer = new TestableBrentOptimizer(1e-10, 1e-10) {
            @Override
            protected double computeObjectiveValue(double x) {
                return function.value(x);
            }
            @Override
            protected double getMin() { return 5.0; } // lo > hi
            @Override
            protected double getMax() { return 0.0; }
            @Override
            protected double getStartValue() { return 2.5; }
            @Override
            protected GoalType getGoalType() { return GoalType.MINIMIZE; }
        };

        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(1.0, result.getPoint(), 1e-7);
    }

    /**
     * Tests the custom convergence checker branch.
     */
    @Test
    public void testCustomConvergenceChecker() {
        UnivariateFunction function = x -> Math.pow(x - 1.0, 2);
        // Force convergence after 1 iteration
        ConvergenceChecker<UnivariatePointValuePair> checker = new MaxIterConvergenceChecker(1);

        BrentOptimizer optimizer = new TestableBrentOptimizer(1e-10, 1e-10, checker) {
            @Override
            protected double computeObjectiveValue(double x) {
                return function.value(x);
            }
            @Override
            protected double getMin() { return 0.0; }
            @Override
            protected double getMax() { return 2.0; }
            @Override
            protected double getStartValue() { return 1.5; }
            @Override
            protected GoalType getGoalType() { return GoalType.MINIMIZE; }
        };

        UnivariatePointValuePair result = optimizer.doOptimize();
        // Result should be valid even if not perfectly converged due to checker
        assertTrue(result.getPoint() > 0);
    }

    /**
     * Tests the branch where parabolic interpolation is skipped due to e (distance) being small.
     */
    @Test
    public void testGoldenSectionFallback() {
        // Function designed to make the parabola fit fail or be skipped
        UnivariateFunction function = x -> Math.abs(x - 1.0);
        BrentOptimizer optimizer = new TestableBrentOptimizer(1e-10, 1e-10) {
            @Override
            protected double computeObjectiveValue(double x) {
                return function.value(x);
            }
            @Override
            protected double getMin() { return 0.0; }
            @Override
            protected double getMax() { return 2.0; }
            @Override
            protected double getStartValue() { return 1.5; }
            @Override
            protected GoalType getGoalType() { return GoalType.MINIMIZE; }
        };

        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(1.0, result.getPoint(), 1e-7);
    }

    /**
     * Tests the edge case where the update step d is smaller than tol1.
     */
    @Test
    public void testSmallStepAdjustment() {
        UnivariateFunction function = x -> Math.pow(x - 1.0, 2);
        BrentOptimizer optimizer = new TestableBrentOptimizer(1e-10, 1e-10) {
            @Override
            protected double computeObjectiveValue(double x) {
                return function.value(x);
            }
            @Override
            protected double getMin() { return 0.0; }
            @Override
            protected double getMax() { return 1.0000000000001; }
            @Override
            protected double getStartValue() { return 1.0; }
            @Override
            protected GoalType getGoalType() { return GoalType.MINIMIZE; }
        };

        UnivariatePointValuePair result = optimizer.doOptimize();
        assertEquals(1.0, result.getPoint(), 1e-10);
    }
}
